insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('1dc5b0ee-a39f-5a60-9146-eab2622ee769', '3a854ee6-9fae-5871-8ee0-9e666de75b0d', 'Phở bò', 'Bac', true, '4 người', 4, 'khoảng 3 giờ (hầm) hoặc 60 phút bản rút gọn', 180, 'xương ống bò 1 kg; thịt bò bắp/nạm 600 g; thịt bò tái (thăn) 300 g; bánh phở 1 kg; hành tây 2 củ, gừng 100 g, hành khô 4 củ; quế, hồi, thảo quả, đinh hương (1 gói gia vị phở); hành lá, mùi, húng quế, giá, chanh, ớt; nước mắm, muối, đường phèn.', '1) Chần xương 5 phút, rửa sạch. 2) Nướng hành, gừng thơm. 3) Hầm xương 2–3 giờ lửa nhỏ, vớt bọt, cho gia vị đã rang thơm vào 30 phút cuối. 4) Luộc nạm/bắp chín, thái mỏng. 5) Nêm nước dùng: nước mắm + đường phèn, vị mặn thanh, không gắt. 6) Trụng bánh phở, xếp thịt, chan nước sôi già, rắc hành mùi.', 'Nước dùng phải sôi thật già mới “chín” được thịt tái; không đun gia vị quá lâu sẽ đắng.', 'kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', NULL, NULL, NULL) on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('f2dc8fd6-0b84-549d-97b2-b7855e7df5c7', 'faa77d86-0b21-50ca-8414-f204602a8b32', 'Bún chả', 'Bac', true, '4 người', 4, 'khoảng 60 phút', 60, 'thịt ba chỉ 400 g; thịt nạc vai xay 400 g; bún tươi 1 kg; đu đủ xanh/cà rốt làm dưa góp; tỏi, ớt, sả (tuỳ chọn), hành tím; nước mắm, đường, giấm, nước dừa hoặc nước lọc; rau sống: xà lách, tía tô, kinh giới, húng.', '1) Ướp thịt miếng và thịt viên với hành tím băm, nước mắm, đường, tiêu, chút dầu ăn 30 phút. 2) Nướng than (hoặc nồi chiên không dầu 200°C, 12–15 phút) đến xém cạnh. 3) Pha nước chấm: nước ấm + đường + nước mắm + giấm, vị chua ngọt mặn cân bằng, thả dưa góp và tỏi ớt. 4) Cho chả nóng vào bát nước chấm, ăn kèm bún và rau sống.', 'Cho chả vào nước chấm khi còn nóng để chả thấm và nước chấm thơm mùi nướng.', 'kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', NULL, NULL, NULL) on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('c53d84df-7758-5a84-92c5-e81a496a96c6', 'e3d7de0c-d541-5277-aa22-2d5a52442ec4', 'Bún bò Huế', 'Trung', true, '4 người', 4, 'khoảng 90 phút', 90, 'bún sợi lớn 1 kg; bắp bò 600 g; giò heo 500 g (tuỳ chọn); chả Huế/chả bò 200 g; sả 6 cây; mắm ruốc Huế 2 muỗng canh; ớt, sa tế; hành tây, hành lá, rau răm; rau ăn kèm: bắp chuối bào, giá, rau thơm.', '1) Luộc bắp bò và giò với sả đập dập, vớt bọt. 2) Hoà mắm ruốc với nước lạnh, để lắng, chỉ lấy nước trong cho vào nồi. 3) Phi sả băm và ớt với dầu màu điều, cho vào nồi tạo màu và vị cay thơm. 4) Nêm muối, đường, nước mắm; thịt chín vớt ra thái. 5) Trụng bún, xếp thịt, chả, chan nước dùng, rắc hành răm.', 'Cay và thơm sả phải rõ nhưng không át vị bò; ăn kèm chanh và ớt tươi.', 'kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', NULL, NULL, NULL) on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('b973c92b-9f88-503e-9e93-50bcce06ff3e', 'b6fcb00f-4477-5f6e-9905-a5626a60d501', 'Mì Quảng gà/tôm thịt', 'Trung', true, '4 người', 4, 'khoảng 60 phút', 60, 'mì Quảng (sợi mì gạo nghệ) 800 g; tôm 300 g; thịt ba chỉ 300 g; trứng cút 12 quả; đậu phộng rang; bánh tráng nướng; rau sống: cải con, bắp chuối, húng quế; nghệ, hành, tỏi; nước dùng gà/heo 800 ml (chỉ chan xâm xấp).', '1) Ướp tôm thịt với nghệ băm, nước mắm, tiêu. 2) Xào tôm thịt săn, cho nước dùng vào nấu thành “nước nhưn” đậm vị. 3) Trụng mì, xếp tôm thịt, trứng cút, chan ít nước nhưn. 4) Rắc đậu phộng, hành lá, bẻ bánh tráng nướng lên trên, trộn đều khi ăn.', 'Thiếu bánh tráng nướng và đậu phộng là mất một nửa chất mì Quảng; rau cải con cay nồng là điểm nhận diện.', 'kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', NULL, NULL, NULL) on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('b092cf44-85b3-58b5-9944-3c3dfdd635e2', '2d478aac-e3e0-5202-a892-cee66eaaa8ca', 'Hủ tiếu Nam Vang', 'Nam', true, '4 người', 4, 'khoảng 90 phút', 90, 'hủ tiếu dai 600 g; xương ống heo 800 g; thịt nạc heo 300 g; tôm 200 g; gan heo 150 g (tuỳ chọn); mực khô nhỏ hoặc củ cải trắng tạo ngọt; cần tây, hẹ, xà lách, giá; tỏi phi, hành phi; thịt băm xào tỏi.', '1) Hầm xương với củ cải, vớt bọt kỹ cho nước trong. 2) Luộc thịt, tôm, gan trong nước dùng, thái lát. 3) Xào thịt băm với tỏi cho thơm. 4) Trụng hủ tiếu vừa mềm (trụng lâu sẽ bở), xếp topping, cho thịt băm, chan nước dùng, rắc hẹ, cần, tỏi phi. 5) Hai cách ăn: chan nước hoặc ăn khô trộn sốt tương đen.', 'Nước dùng hủ tiếu cần vị ngọt thanh từ xương và củ cải, không nêm đường gắt.', 'kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', NULL, NULL, NULL) on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('6c890c6a-2613-54dc-8f66-d3b5509f3f8f', '21d9b04e-493a-54a1-bd40-c42814b69c7a', 'Cơm tấm sườn bì chả', 'Nam', true, '4 người', 4, 'khoảng 75 phút', 75, 'gạo tấm 600 g; sườn cốt lết 600 g; bì heo + thính; chả trứng (trứng, thịt băm, miến, nấm mèo); sả, tỏi, mật ong, sữa tươi (ướp sườn mềm); mỡ hành; đồ chua cà rốt — củ cải; nước mắm pha chua ngọt.', '1) Ướp sườn với sả tỏi băm, nước mắm, mật ong, sữa, tiêu ít nhất 1 giờ (tốt nhất qua đêm). 2) Nướng sườn lửa vừa đến xém thơm, phết mỡ hành. 3) Nấu cơm tấm hơi khô hơn cơm thường. 4) Hấp chả trứng chín, cắt miếng. 5) Bày cơm, sườn, bì, chả, đồ chua, chan mỡ hành và nước mắm pha.', 'Nước mắm cơm tấm phải sánh nhẹ và ngọt rõ hơn nước chấm bún chả; sườn ngon nhất khi nướng than.', 'kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', NULL, NULL, NULL) on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('19071b2d-c768-5b04-90ff-5f4eb8a218a3', '78302447-7078-5814-80fc-5154f324349e', 'Phở gà', 'Bac', true, '6–8 người', NULL, '120 phút', 120, '1 con gà mái (2 kg); 2 bộ xương gà; sá sùng (nấu nước dùng); hành khô, hành tây, gừng, rễ mùi, rễ hành lá, hạt mùi; mắm ngon, muối, đường phèn; hành lá, rau mùi, lá chanh; bánh phở tươi; giấm tỏi, chanh, ớt', 'Công thức tham khảo từ VnExpress — Bùi Thủy, «Cách làm phở gà Hà Nội truyền thống» (18/8/2023), chưa nấu thử.
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('6b40c559-45a4-531a-b06a-a99e6247f5c6', 'f5c5fee1-e9e6-5a5a-9e12-ea6d2daaa016', 'Bún thang', 'Bac', true, '4–5 người', NULL, NULL, NULL, 'Gà ta 1 con (1,2–1,3 kg); Trứng gà 2 quả; Giò lụa 100 gram; Xương hom lợn 500 gram; Tôm khô 50 gram; Sá sùng 2–3 con hoặc 2–3 cái râu mực khô; Bún tươi 1,5 kg; Nấm hương 20 gram; Củ cải sợi khô 50 gram; Hành tây 1 củ vừa; Hành khô 6 củ; Rau răm, gừng, hành lá, chanh, ớt; Gia vị: mắm tôm, nước mắm, bột ngọt, dầu ăn, hạt nêm, muối, giấm, đường trắng, tinh dầu cà cuống (nếu có)', 'Công thức tham khảo từ VnExpress — độc giả Phùng Thơm, «Bún thang chuẩn vị Hà Nội» (27/8/2021), chưa nấu thử.
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('eb6a8670-4f23-513c-9edf-760c9d929473', '5f8d8159-d075-5f8e-a1b3-6cb029f1007c', 'Bún đậu mắm tôm', 'Bac', true, NULL, NULL, NULL, NULL, 'Đậu phụ chiên 10 miếng; Thịt ba chỉ 500gr; Chả cốm 300gr; Bún tươi 1kg; Mắm tôm 1/2 bát; Ớt băm 1 muỗng cà phê; Nước cốt chanh 1 muỗng canh; Đường trắng 1 muỗng canh; Bột ngọt 1 muỗng cà phê; Dầu ăn 6 muỗng canh; Tía tô 100gr, rau thơm các loại 50gr; Dưa chuột 3 quả', 'Công thức tham khảo từ VietNamNet — «Cách làm bún đậu mắm tôm ngon như của bà Nội phim Gạo nếp gạo tẻ» (19/9/2018), chưa nấu thử.
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, servings, time_text, total_minutes, ingredients_text, steps_text, tip, source_code, recipe_source, source_url, source_accessed_date, recipe_status) values ('dbc97abb-f306-56ea-a6a4-de58c91f396c', 'bc63b8e5-6940-570b-aa4c-17ec19e6d1e5', 'Chả cá Lã Vọng', 'Bac', true, '4–6 người', NULL, '90 phút', 90, '1 kg cá lăng phi lê; 1 củ riềng bánh tẻ; 1 củ nghệ tươi; mẻ (cơm mẻ); nước mắm ngon, mắm tôm, mì chính, hạt tiêu, tinh dầu cà cuống; thì là, hành hoa, húng Láng, rau mùi; lạc rang, hành phi, chanh, ớt, hành tây (tùy chọn); mỡ lợn hoặc mỡ gà ta; bún', 'Công thức tham khảo từ VnExpress — Bùi Thủy, «Cách làm chả cá Hà Nội hương vị xưa» (23/2/2023), chưa nấu thử.
