insert into diet_modes (code, name_vi, description_vi, rule_vi, sort_order, max_kcal_per_serving, max_fat_g, excluded_cooking_methods, min_protein_g, min_protein_per_100kcal, max_carb_g) values ('binh_thuong', 'Bình thường', 'Không loại trừ món nào. Dùng khi không theo chế độ đặc biệt.', 'Không có quy tắc loại trừ.', 1, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into diet_modes (code, name_vi, description_vi, rule_vi, sort_order, max_kcal_per_serving, max_fat_g, excluded_cooking_methods, min_protein_g, min_protein_per_100kcal, max_carb_g) values ('an_chay', 'Ăn chay', 'Không thịt, không cá/hải sản. Được phép trứng/sữa trừ khi ghi chú khác. Cần xác nhận khi biên tập công thức vì nước mắm/mỡ hành có thể dùng trong món chay.', 'an_chay = false khi tên món (theo từ trọn) có: bò, gà, heo, thịt, cá, tôm, cua, ốc, hến, mực, vịt, lòng, sườn, chả, nem, mắm, tré, mọc — hoặc công thức đầy đủ có thịt/cá/hải sản. Chỉ true khi có công thức xác nhận; còn lại NULL. Không phụ thuộc số liệu dinh dưỡng.', 2, NULL, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into diet_modes (code, name_vi, description_vi, rule_vi, sort_order, max_kcal_per_serving, max_fat_g, excluded_cooking_methods, min_protein_g, min_protein_per_100kcal, max_carb_g) values ('an_kieng_giam_can', 'Ăn kiêng giảm cân', 'Ưu tiên món ít năng lượng trong một khẩu phần.', 'an_kieng = kcal/phần <= 450 (chỉ tính khi có số liệu theo khẩu phần từ Bảng TPTP VN, QĐ1=B).', 3, 450, NULL, NULL, NULL, NULL, NULL) on conflict do nothing;
insert into diet_modes (code, name_vi, description_vi, rule_vi, sort_order, max_kcal_per_serving, max_fat_g, excluded_cooking_methods, min_protein_g, min_protein_per_100kcal, max_carb_g) values ('it_dau_mo', 'Ít dầu mỡ', 'Ít chất béo trong một khẩu phần và không phải món chiên/xào.', 'it_dau_mo: fat/phần > 10 g → false; fat ≤ 10 g và cách nấu là xao/chien_ran → false; fat ≤ 10 g và chưa có cách nấu → NULL; còn lại → true. Chỉ tính khi có số liệu theo khẩu phần từ Bảng TPTP VN (QĐ1=B).', 4, NULL, 10, array['xao', 'chien_ran']::text[], NULL, NULL, NULL) on conflict do nothing;
